package game.items;

import edu.monash.fit2099.engine.items.Item;

/**
 * Represents a piece of meteorite ore generated by celestial impacts.
 *
 * <p>Meteorite ore is portable and can be collected by actors.
 * It may be used for future celestial crafting or recovery mechanics.</p>
 *
 * @author Chin Kai Xuan 35730374
 * @version 1.0.0
 */
public final class MeteoriteOre extends Item {

    /**
     * Creates a collectible piece of meteorite ore.
     */
    public MeteoriteOre() {
        super("Meteorite Ore", '*');
        this.makePortable();
    }
}
